const input = $input.first().json;
const errors = [];

const isObject = (value) =>
  value !== null &&
  typeof value === 'object' &&
  !Array.isArray(value);

if (input.schemaVersion !== '1.0') {
  errors.push('schemaVersion must be 1.0');
}

if (input.resolution?.status !== 'RESOLVED') {
  errors.push('resolution.status must be RESOLVED');
}

const extractionId = input.extraction?.id;

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(String(extractionId ?? ''))) {
  errors.push('extraction.id must be a valid UUID');
}

if (!isObject(input.candidateProfile)) {
  errors.push('candidateProfile must be an object');
}

if (!isObject(input.assessmentContext)) {
  errors.push('assessmentContext must be an object');
}

if (!isObject(input.gradeGuide)) {
  errors.push('gradeGuide must be an object');
}

const dimensions = input.gradeGuide?.dimensions;

if (!Array.isArray(dimensions) || dimensions.length !== 7) {
  errors.push('gradeGuide.dimensions must contain exactly 7 dimensions');
}

const dimensionCodes = Array.isArray(dimensions)
  ? dimensions.map((dimension) => dimension.code)
  : [];

if (new Set(dimensionCodes).size !== dimensionCodes.length) {
  errors.push('gradeGuide dimension codes must be unique');
}

const totalWeight = Array.isArray(dimensions)
  ? dimensions.reduce(
      (total, dimension) =>
        total + Number(dimension.weight ?? 0),
      0
    )
  : 0;

if (totalWeight !== 100) {
  errors.push(`gradeGuide dimension weights must total 100, found ${totalWeight}`);
}

const targetGradeCode =
  input.assessmentContext?.targetGradeCode;

const guideTargetGradeCode =
  input.gradeGuide?.targetGrade?.code;

if (
  !targetGradeCode ||
  targetGradeCode !== guideTargetGradeCode
) {
  errors.push(
    'assessment target grade must match gradeGuide.targetGrade.code'
  );
}

if (
  input.gradeGuide?.decisionPolicy?.finalGradeAssignedBy !==
  'DETERMINISTIC_ENGINE'
) {
  errors.push(
    'final grade must be assigned by DETERMINISTIC_ENGINE'
  );
}

if (errors.length > 0) {
  throw new Error(
    `INVALID_GRADE_ENGINE_INPUT: ${errors.join('; ')}`
  );
}

return [
  {
    json: input,
  },
];

parameters.inputSchema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://talentai.local/schemas/grade-evidence-scoring-v1.schema.json",
  "title": "TalentAI Grade Evidence Scoring v1",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "assessmentSummary",
    "dimensions",
    "warnings"
  ],
  "properties": {
    "schemaVersion": {
      "const": "1.0"
    },
    "assessmentSummary": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000
    },
    "dimensions": {
      "type": "array",
      "minItems": 7,
      "maxItems": 7,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "code",
          "score",
          "confidence",
          "evidence",
          "rationale"
        ],
        "properties": {
          "code": {
            "type": "string",
            "enum": [
              "JAVA_CORE",
              "SPRING_ECOSYSTEM",
              "DATABASE",
              "DISTRIBUTED_SYSTEMS",
              "TESTING",
              "SOFTWARE_ARCHITECTURE",
              "OBSERVABILITY_DEVOPS"
            ]
          },
          "score": {
            "type": "integer",
            "minimum": 0,
            "maximum": 4
          },
          "confidence": {
            "type": "string",
            "enum": ["HIGH", "MEDIUM", "LOW"]
          },
          "evidence": {
            "type": "array",
            "maxItems": 5,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["quote", "source"],
              "properties": {
                "quote": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 1000
                },
                "source": {
                  "type": "string",
                  "enum": [
                    "PROFILE_SKILL",
                    "WORK_EXPERIENCE",
                    "EDUCATION",
                    "WARNING",
                    "OTHER"
                  ]
                }
              }
            }
          },
          "rationale": {
            "type": "string",
            "minLength": 1,
            "maxLength": 1500
          }
        }
      }
    },
    "warnings": {
      "type": "array",
      "maxItems": 20,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 1000
      }
    }
  }
}

parameters.jsCode:
const chainResult = $input.first().json;

let scoringResult =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  scoringResult &&
  typeof scoringResult === 'object' &&
  scoringResult.output &&
  !scoringResult.dimensions
) {
  scoringResult = scoringResult.output;
}

if (typeof scoringResult === 'string') {
  try {
    scoringResult = JSON.parse(scoringResult);
  } catch (error) {
    throw new Error(
      `INVALID_EVIDENCE_SCORING_JSON: ${error.message}`
    );
  }
}

const promptContext =
  $('Build Evidence Scoring Prompt').first().json;

const gradeEngineInput =
  promptContext.gradeEngineInput;

const expectedDimensions =
  gradeEngineInput.gradeGuide.dimensions;

const expectedCodes =
  expectedDimensions.map((dimension) => dimension.code);

const errors = [];

if (
  !scoringResult ||
  typeof scoringResult !== 'object' ||
  Array.isArray(scoringResult)
) {
  errors.push('scoring result must be an object');
}

if (scoringResult?.schemaVersion !== '1.0') {
  errors.push('scoring schemaVersion must be 1.0');
}

if (!Array.isArray(scoringResult?.dimensions)) {
  errors.push('dimensions must be an array');
}

const assessments =
  Array.isArray(scoringResult?.dimensions)
    ? scoringResult.dimensions
    : [];

if (assessments.length !== expectedCodes.length) {
  errors.push(
    `expected ${expectedCodes.length} dimensions, received ${assessments.length}`
  );
}

const receivedCodes =
  assessments.map((assessment) => assessment.code);

if (new Set(receivedCodes).size !== receivedCodes.length) {
  errors.push('dimension codes must be unique');
}

for (const expectedCode of expectedCodes) {
  if (!receivedCodes.includes(expectedCode)) {
    errors.push(`missing dimension: ${expectedCode}`);
  }
}

for (const receivedCode of receivedCodes) {
  if (!expectedCodes.includes(receivedCode)) {
    errors.push(`unexpected dimension: ${receivedCode}`);
  }
}

const allowedConfidences =
  new Set(['HIGH', 'MEDIUM', 'LOW']);

const profileCorpus =
  JSON.stringify(gradeEngineInput.candidateProfile)
    .toLocaleLowerCase();

for (const assessment of assessments) {
  if (
    !Number.isInteger(assessment.score) ||
    assessment.score < 0 ||
    assessment.score > 4
  ) {
    errors.push(
      `${assessment.code}: score must be an integer from 0 to 4`
    );
  }

  if (!allowedConfidences.has(assessment.confidence)) {
    errors.push(
      `${assessment.code}: invalid confidence`
    );
  }

  if (!Array.isArray(assessment.evidence)) {
    errors.push(
      `${assessment.code}: evidence must be an array`
    );
    continue;
  }

  if (
    assessment.score > 0 &&
    assessment.evidence.length === 0
  ) {
    errors.push(
      `${assessment.code}: a positive score requires evidence`
    );
  }

  for (const evidence of assessment.evidence) {
    const quote = String(evidence?.quote ?? '').trim();

    if (!quote) {
      errors.push(
        `${assessment.code}: evidence quote is empty`
      );
      continue;
    }

    if (
      !profileCorpus.includes(quote.toLocaleLowerCase())
    ) {
      errors.push(
        `${assessment.code}: evidence quote is not traceable to candidateProfile`
      );
    }
  }

  if (
    typeof assessment.rationale !== 'string' ||
    !assessment.rationale.trim()
  ) {
    errors.push(
      `${assessment.code}: rationale is required`
    );
  }
}

if (!Array.isArray(scoringResult?.warnings)) {
  errors.push('warnings must be an array');
}

if (
  typeof scoringResult?.assessmentSummary !== 'string' ||
  !scoringResult.assessmentSummary.trim()
) {
  errors.push('assessmentSummary is required');
}

if (errors.length > 0) {
  throw new Error(
    `INVALID_DIMENSION_ASSESSMENTS: ${errors.join('; ')}`
  );
}

const assessmentByCode =
  new Map(
    assessments.map((assessment) => [
      assessment.code,
      assessment,
    ])
  );

const orderedAssessments =
  expectedCodes.map((code) => assessmentByCode.get(code));

return [
  {
    json: {
      gradeEngineInput,
      scoringMetadata: {
        model: promptContext.scoringModel,
        promptVersion: promptContext.promptVersion,
      },
      evidenceScoring: {
        schemaVersion: scoringResult.schemaVersion,
        assessmentSummary:
          scoringResult.assessmentSummary.trim(),
        dimensions: orderedAssessments,
        warnings: scoringResult.warnings,
      },
    },
  },
];

const validated = $input.first().json;

const gradeEngineInput =
  validated.gradeEngineInput;

const evidenceScoring =
  validated.evidenceScoring;

const scoringMetadata =
  validated.scoringMetadata;

const dimensions =
  gradeEngineInput.gradeGuide.dimensions;

const targetGrade =
  gradeEngineInput.gradeGuide.targetGrade;

const evidencePolicy =
  gradeEngineInput.gradeGuide.evidencePolicy;

const confidenceRank = {
  LOW: 1,
  MEDIUM: 2,
  HIGH: 3,
};

const minimumConfidence =
  evidencePolicy.minimumConfidenceForScoring ?? 'MEDIUM';

const minimumConfidenceRank =
  confidenceRank[minimumConfidence];

const missingEvidenceScore =
  Number(evidencePolicy.missingEvidenceScore ?? 0);

const assessmentByCode = new Map(
  evidenceScoring.dimensions.map((assessment) => [
    assessment.code,
    assessment,
  ])
);

const minimumLevels =
  targetGrade.minimumDimensionLevels ?? {};

const reviewReasons = [];
const dimensionAssessments = [];

let weightedTotal = 0;

for (const dimension of dimensions) {
  const assessment =
    assessmentByCode.get(dimension.code);

  if (!assessment) {
    throw new Error(
      `MISSING_VALIDATED_DIMENSION: ${dimension.code}`
    );
  }

  const modelScore =
    Number(assessment.score);

  const confidence =
    assessment.confidence;

  const confidenceAccepted =
    confidenceRank[confidence] >= minimumConfidenceRank;

  const effectiveScore =
    confidenceAccepted
      ? modelScore
      : missingEvidenceScore;

  const weight =
    Number(dimension.weight);

  const weightedScore =
    (effectiveScore / 4) * weight;

  weightedTotal += weightedScore;

  const hasRequiredMinimum =
    Object.prototype.hasOwnProperty.call(
      minimumLevels,
      dimension.code
    );

  const minimumRequired =
    hasRequiredMinimum
      ? Number(minimumLevels[dimension.code])
      : null;

  const minimumMet =
    minimumRequired === null ||
    effectiveScore >= minimumRequired;

  if (
    hasRequiredMinimum &&
    !confidenceAccepted
  ) {
    reviewReasons.push(
      `${dimension.code}: confidence ${confidence} is below required ${minimumConfidence}`
    );
  }

  dimensionAssessments.push({
    code: dimension.code,
    title: dimension.title,
    weight,
    mandatory: Boolean(dimension.mandatory),

    modelScore,
    effectiveScore,
    confidence,
    confidenceAccepted,

    weightedScore:
      Math.round(weightedScore * 100) / 100,

    minimumRequired,
    minimumMet,

    evidence: assessment.evidence,
    rationale: assessment.rationale,
  });
}

const overallScore =
  Math.round(weightedTotal * 100) / 100;

const minimumOverallScore =
  Number(targetGrade.minimumOverallScore);

const thresholdMet =
  overallScore >= minimumOverallScore;

const mandatoryChecks =
  Object.entries(minimumLevels).map(
    ([code, minimumRequired]) => {
      const assessment =
        dimensionAssessments.find(
          (item) => item.code === code
        );

      if (!assessment) {
        throw new Error(
          `MANDATORY_DIMENSION_NOT_FOUND: ${code}`
        );
      }

      return {
        code,
        minimumRequired:
          Number(minimumRequired),
        effectiveScore:
          assessment.effectiveScore,
        met:
          assessment.effectiveScore >=
          Number(minimumRequired),
      };
    }
  );

const mandatoryDimensionsMet =
  mandatoryChecks.every((check) => check.met);

const reviewRequired =
  reviewReasons.length > 0;

let decision;

if (reviewRequired) {
  decision = 'REVIEW_REQUIRED';
} else if (
  thresholdMet &&
  mandatoryDimensionsMet
) {
  decision = 'MEETS_TARGET';
} else {
  decision = 'BELOW_TARGET';
}

const engineVersion = '1.0';

const workflowExecutionId =
  String($execution.id);

if (!workflowExecutionId) {
  throw new Error(
    'WORKFLOW_EXECUTION_ID_NOT_AVAILABLE'
  );
}

const persistenceParameters = [
  workflowExecutionId,
  gradeEngineInput.extraction.id,
  gradeEngineInput.gradeGuide.id,
  gradeEngineInput.gradeGuide.version,
  gradeEngineInput.assessmentContext.targetGradeCode,
  scoringMetadata.model,
  scoringMetadata.promptVersion,
  engineVersion,
  JSON.stringify(dimensionAssessments),
  overallScore,
  minimumOverallScore,
  thresholdMet,
  mandatoryDimensionsMet,
  decision,
  JSON.stringify(reviewReasons),
  JSON.stringify(evidenceScoring.warnings),
  evidenceScoring.assessmentSummary,
];

return [
  {
    json: {
      schemaVersion: '1.0',

      gradeEngineInput,

      scoringMetadata: {
        model: scoringMetadata.model,
        promptVersion:
          scoringMetadata.promptVersion,
        engineVersion,
      },

      evidenceScoring,

      deterministicResult: {
        targetGradeCode:
          gradeEngineInput
            .assessmentContext
            .targetGradeCode,

        overallScore,
        minimumOverallScore,
        thresholdMet,
        mandatoryDimensionsMet,
        mandatoryChecks,
        reviewRequired,
        reviewReasons,
        decision,
        dimensionAssessments,
      },

      persistenceParameters,
    },
  },
];

const persisted =
  $input.first().json;

const calculated =
  $('Calculate Deterministic Grade')
    .first()
    .json;

const engineInput =
  calculated.gradeEngineInput;

const candidate =
  engineInput.candidateProfile?.candidate ?? {};

return [
  {
    json: {
      schemaVersion: '1.0',

      assessmentId:
        persisted.assessmentId,

      extractionId:
        persisted.extractionId,

      candidate: {
        fullName:
          candidate.fullName ?? '',
      },

      assessmentContext: {
        positionCode:
          engineInput
            .assessmentContext
            .positionCode,

        targetGradeCode:
          persisted.targetGradeCode,

        jobDescription:
          engineInput
            .assessmentContext
            .jobDescription,
      },

      gradeGuide: {
        id:
          persisted.gradeGuideId,

        version:
          persisted.gradeGuideVersion,
      },

      score: {
        overall:
          Number(persisted.overallScore),

        minimumRequired:
          Number(
            persisted.minimumOverallScore
          ),

        thresholdMet:
          persisted.thresholdMet,

        mandatoryDimensionsMet:
          persisted.mandatoryDimensionsMet,
      },

      decision:
        persisted.decision,

      dimensionAssessments:
        persisted.dimensionAssessments,

      reviewReasons:
        persisted.reviewReasons,

      modelWarnings:
        persisted.modelWarnings,

      assessmentSummary:
        persisted.assessmentSummary,

      metadata: {
        scoringModel:
          persisted.scoringModel,

        promptVersion:
          persisted.promptVersion,

        engineVersion:
          persisted.engineVersion,

        status:
          persisted.status,

        createdAt:
          persisted.createdAt,

        wasInserted:
          persisted.wasInserted,
      },
    },
  },
];
